command:
return (async () => {
  const mode = args[0];
  if (!["on", "off"].includes(mode)) return;
  const last = args.at(-1) ?? {};
  const targetDocument = last.tokenUuid ? await fromUuid(last.tokenUuid) : null;
  const targetToken = targetDocument ? targetDocument.object : canvas.tokens?.get(last.tokenId);
  const targetActor = (typeof actor !== "undefined" && actor) || targetDocument?.actor || targetToken?.actor || (last.actorUuid ? await fromUuid(last.actorUuid) : null);
  if (!targetActor) return;

  if (mode === "off") {
    if (!last.origin) return;
    const lingering = targetActor.effects.find(e => e.flags?.myTentacle?.origin === last.origin);
    if (lingering) await lingering.delete();
    return;
  }
  // Follow an aura's origin to the caster, rather than using its recipient's roll data.
  const sourceUuid = last.origin || last.efData?.system?.origin?.item || last.efData?.system?.origin?.actor;
  if (!sourceUuid) return ui.notifications.warn("无法确定施法来源，已停止宏。");
  let source = await fromUuid(sourceUuid);
  const visited = new Set();
  for (let depth = 0; source?.documentName === "ActiveEffect" && depth < 10; depth++) {
    if (visited.has(source.uuid)) return;
    visited.add(source.uuid);
    const origin = source.origin || source.system?.origin?.item || source.system?.origin?.actor;
    source = origin ? await fromUuid(origin) : source.parent;
  }
  const caster = source?.documentName === "Actor" ? source : source?.actor;
  const saveDC = Number(foundry.utils.getProperty(caster, "system.attributes.spell.dc"));
  if (!caster || !Number.isFinite(saveDC) || saveDC <= 0) return ui.notifications.warn("无法确定施法者或豁免 DC，已停止宏。");

  const saves = await targetActor.rollSavingThrow({ ability: "str", target: saveDC }, {}, { data: { flavor: "Tentacles save vs DC " + saveDC } });
  const save = saves?.[0];
  if (!save || !Number.isFinite(save.total)) return;
  if (save.total >= saveDC) {
    const aura = last.effectId ? targetActor.effects.get(last.effectId) : targetActor.effects.find(e => e.origin === last.origin);
    if (aura) await aura.delete();
    return;
  }
  // V14 changes and duration are authored directly in their native data model.
  const effectData = {
    name: "艾伐黑触手—束缚", img: "icons/creatures/tentacles/tentacles-suctioncups-pink.webp",
    origin: last.origin, type: "base", transfer: false,
    system: { origin: { actor: caster.uuid, item: source?.documentName === "Item" ? source.uuid : null }, changes: [
      { _id: foundry.utils.randomID(), key: "flags.midi-qol.OverTime", type: "custom", phase: "initial", priority: 20, conditions: "{}", replacement: "",
        value: "turn=start,allowIncapacitated=true,rollType=check,saveAbility=str,saveDC=" + saveDC + ",saveDamage=fulldamage,saveRemove=true,saveMagic=true,actionSave=dialog,damageBeforeSave=true,damageRoll=3d6,damageType=bludgeoning,rollMode=publicroll," },
      { _id: foundry.utils.randomID(), key: "macro.execute", type: "custom", phase: "initial", priority: 20, conditions: "{}", replacement: "",
        value: "Compendium.dnd5e_classpack.macro.Macro.q0ytDPXNkJoqabx5" }
    ] },
    duration: { value: 10, units: "rounds", expiry: "turnStart" }, statuses: ["restrained"], flags: { myTentacle: { origin: last.origin } }
  };
  await targetActor.createEmbeddedDocuments("ActiveEffect", [effectData]);
})();
